                    i //= d
                result.append(d)
            d = 3
            while d*d <= i:
                if i%d == 0:
                    while i%d == 0:
                        i //= d
                    result.append(d)
                d += 2
            if i != 1:
                result.append(i)
            return result

        union_find = UnionFind(len(A))
        nodesWithCommonFactor = collections.defaultdict(int)
        for i in xrange(len(A)):
            for factor in prime_factors(A[i]):
