class Solution(object):
    def regionsBySlashes(self, grid):
        """
        :type grid: List[str]
        :rtype: int
        """
        def index(n, i, j, k):
            return (i*n + j)*4 + k

        union_find = UnionFind(len(grid)**2 * 4)
        N, E, S, W = range(4)
