class NodeIter(Node):
    ops = {'+':operator.add, '-':operator.sub, '*':operator.mul, '/':operator.div}

    def __init__(self, val):
        self.val = val
        self.left = None 
        self.right = None

    def evaluate(self):
        result = [0]
        stk = [(1, (self, result))]
        while stk:
            step, args = stk.pop()
            if step == 1:
                node, ret = args
                if node.val.isdigit():
                    ret[0] = int(node.val)
                    continue
                ret1, ret2 = [0], [0]
                stk.append((2, (node, ret1, ret2, ret)))
                stk.append((1, (node.right, ret2)))
                stk.append((1, (node.left, ret1)))
            elif step == 2:
                node, ret1, ret2, ret = args
                ret[0] = NodeIter.ops[node.val](ret1[0], ret2[0])
        return result[0]


