class Solution(object):
    def score(self, cards, x):
        cnt1 = [0]*26
        cnt2 = [0]*26
        cnt3 = 0
        for s in cards:
            if x not in s:
                continue
            if s[0] == x == s[1]:
                cnt3 += 1
            elif s[0] == x:
