            ret += ret[:len(target)//2][::-1]
            if ret > target:
                return ret
            if len(target)%2:
                result.pop()
        while result:
            c = ord(result.pop())-ord('a')
            cnt[c] += 2
            for i in xrange(c+1, len(cnt)):
                if not cnt[i]:
                    continue
                cnt[i] -= 2
                result.append(chr(ord('a')+i))
                for j in xrange(len(cnt)):
                    if not cnt[j]:
