class Solution(object):
    def evaluateExpression(self, expression):
        """
        :type expression: str
        :rtype: int
        """
        LOOKUP = {
            "add":lambda a, b: a+b,
            "sub":lambda a, b: a-b,
            "mul":lambda a, b: a*b,
            "div":lambda a, b: a//b
        }

