                    curr -= len(digits)//2*9
                    for tight in xrange(2):
                        if not dp[curr][tight]:
                            continue
                        bound = digits[i] if tight else 9
                        for d in xrange(bound+1):
                            new_dp[curr-d if i&1 else curr+d][tight and d == bound] += dp[curr][tight]
