                dp, cnt = (hull[0][0]*x+hull[0][1])+(x*x+x)//2+l, hull[0][2]+1
                line = (-x, dp+(x*x-x)//2, cnt)
                while len(hull) >= 2 and not check(hull[-2], hull[-1], line):
                    hull.pop()
                hull.append(line)
            return dp, cnt

