class Solution(object):
    def sumOfPrimesInRange(self, n):
        """
        :type n: int
        :rtype: int
        """
        def reverse(n):
            result = 0
            while n:
                n, r = divmod(n, 10)
                result = result*10+r
            return result

        left, right = n, reverse(n)
        if left > right:
            left, right = right, left
        return PREFIX[right+1]-PREFIX[left]

