class Solution(object):
    def finishTime(self, n, edges, baseTime):
        """
        :type n: int
        :type edges: List[List[int]]
        :type baseTime: List[int]
        :rtype: int
        """
        POS_INF, NEG_INF = float("inf"), float("-inf")
        def iter_dfs():
            dp = [0]*n
            stk = [(1, 0)]
            while stk:
                step, u = stk.pop()
                if step == 1:
                    stk.append((2, u))
                    for v in reversed(adj[u]):
