                    dp[u] = ((2*mx-mn) if mx is not NEG_INF else 0)+baseTime[u]
            return dp[0]

        adj = [[] for _ in xrange(n)]
        for u, v in edges:
            adj[u].append(v)
        return iter_dfs()


