        """
        :type l: int
        :type r: int
        :type k: int
        :rtype: int
        """
        def count(n):
            if n < 0:
                return 0
            digits = map(int, str(n))
            result = 1
            bound = next((i for i in xrange(1, len(digits)) if abs(digits[i]-digits[i-1]) > k), len(digits))
