                for j in xrange(len(dp)):
                    prefix[j+1] = prefix[j]+dp[j]
                result += prefix[(digits[0]-1 if i == 0 else 9)+1]-prefix[1]
                if 1 <= i <= bound:
                    result += max(prefix[min(digits[i-1]+k, digits[i]-1)+1]-prefix[max(digits[i-1]-k, 0)], 0)
            return result

